# Generated by build.py from recipe.yml for recipe webtransport-send-datagrams-and-streams. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'state.json'), "{`"player`":1,`"x`":3,`"y`":4}")
[IO.File]::WriteAllText((Join-Path $PWD 'log.txt'), "level 2 loaded")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
cmd /c 'openssl rand -out big.bin 100000'
cmd /c 'openssl rand -out d1100.bin 1100'
cmd /c 'openssl rand -out d1099.bin 1099'
$server0 = Start-Process surl -ArgumentList '--cert', 'server.pem', '--key', 'server.key', '--user', 'player1:secret', 'webtransport://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -m 10 --cacert server.pem -u player1:secret -d @state.json "webtransport://127.0.0.1:8080/game?wt=datagram" } finally { Stop-Process $server0 }
